  const stamped = compareVersions(os, "10.0") >= 0 || compareVersions(subsystem, "10.0") >= 0 ? "10.0" : undefined
  const windows = newer.reduce<string | undefined>((all, name) => higher(all, NEWER_WINDOWS[name]), stamped)
  return {
    file,
    format: "pe",
